import json
for run in ['0021','0022']:
    path=f'.archon-horizon/runs/{run}/sessions/0001-horizon-interactive/transcript.jsonl'
    lines=open(path).readlines()
    print(f'===== run {run}: {len(lines)} events =====')
    # print last assistant text
    texts=[]
    for l in lines:
        try: e=json.loads(l)
        except: continue
        t=e.get('type') or e.get('role')
        if t=='assistant' or e.get('message',{}).get('role')=='assistant':
            msg=e.get('message',e)
            c=msg.get('content')
            if isinstance(c,list):
                for b in c:
                    if b.get('type')=='text': texts.append(b['text'])
            elif isinstance(c,str): texts.append(c)
    if texts:
        print(texts[-1][:3000])
    else:
        print('(no assistant text found)')
"

